// 위젯 6개(확률, Teacher Forcing, LSTM, 기울기, 샘플링, 빔)의 원본 스크립트. 화면 테마·인쇄·읽기 진행 막대 부분은 뺐다.
export const ORIGINAL_SCRIPT: string = "'use strict';\n(() => {\n const $ = id => document.getElementById(id);\n const num = id => Number($(id).value);\n const on = (id, event, fn) => $(id).addEventListener(event, fn);\n const fixed = (x,n=4) => Number(x).toFixed(n);\n const pct = (x,n=1) => (100*x).toFixed(n)+'%';\n const esc = value => String(value).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n const sigmoid = w => w >= 0 ? 1/(1+Math.exp(-w)) : Math.exp(w)/(1+Math.exp(w));\n function barRows(items){\n  return items.map(([label,p],i)=>`<div class=\"bar-row\"><span>${esc(label)}</span><div class=\"bar-track\"><div class=\"bar-fill ${i===1?'alt':''}\" style=\"width:${p*100}%\"></div></div><span class=\"val\">${pct(p,0)}</span></div>`).join('');\n }\n\n // 1. A single specified token path, with EOS explicitly distinguished.\n function updateProbability(){\n  const ps=[1,2,3,4].map(i=>num('p'+i)/100);\n  ps.forEach((p,i)=>$('p'+(i+1)+'Val').textContent=pct(p,0));\n  const useEos=$('includeEos').checked;\n  const selected=ps.slice(0,useEos?4:3);\n  const probability=selected.reduce((a,b)=>a*b,1);\n  $('probCalc').textContent=selected.map(p=>fixed(p,2)).join(' × ')+' = '+fixed(probability,6);\n  $('probKind').textContent=useEos?'완성 문장 확률 · 종료 포함':'세 토큰 접두사의 확률 · 종료 제외';\n  $('probValue').textContent=pct(probability,3);\n  $('probLoss').textContent=fixed(-Math.log(probability));\n  $('p4').disabled=!useEos;\n }\n [1,2,3,4].forEach(i=>on('p'+i,'input',updateProbability));\n on('includeEos','change',updateProbability);\n on('probReset','click',()=>{[80,60,50,90].forEach((v,i)=>$('p'+(i+1)).value=v);$('includeEos').checked=true;updateProbability();});\n updateProbability();\n\n // 2. Teacher forcing vs a fixed greedy generation path, for one toy model.\n let tfMode='train', tfStep=0;\n const target=['나는','너를','사랑해','<EOS>'];\n const tfTrainDistributions=[\n  [['나는',.4],['그는',.6]],\n  [['너를',.6],['당신을',.3],['그를',.1]],\n  [['사랑해',.5],['좋아해',.3],['기억해',.2]],\n  [['<EOS>',.9],['정말',.1]]\n ];\n const tfInferDistributions=[tfTrainDistributions[0],\n  [['너를',.2],['그녀를',.7],['나를',.1]],\n  [['좋아해',.7],['사랑해',.2],['기억해',.1]],\n  tfTrainDistributions[3]\n ];\n const argmax = items => items.reduce((best,next)=>next[1]>best[1]?next:best)[0];\n function updateTeacher(){\n  const train=tfMode==='train';\n  const distributions=train?tfTrainDistributions:tfInferDistributions;\n  const tokens=train?target:tfInferDistributions.map(argmax);\n  const input=tfStep===0?'<BOS>':tokens[tfStep-1];\n  const d=distributions[tfStep], best=argmax(d);\n  $('tfTrain').setAttribute('aria-pressed',String(train));\n  $('tfInfer').setAttribute('aria-pressed',String(!train));\n  $('tfStepName').textContent=`단계 ${tfStep+1} · Decoder에 넣는 토큰`;\n  $('tfInput').textContent=input;\n  $('tfState').textContent=`이 토큰의 임베딩과 이전 상태 hᴰ${tfStep}, cᴰ${tfStep}를 함께 사용합니다.`;\n  $('tfBars').innerHTML=barRows(d);\n  $('tfTimeline').innerHTML=tokens.map((tok,i)=>`<span class=\"token-chip ${i===tfStep?'current':''}\">${i+1}. ${esc(tok)}</span>`).join('');\n  if(train){\n   const p=d.find(x=>x[0]===target[tfStep])[1];\n   $('tfExplanation').textContent=`현재 정답은 ‘${target[tfStep]}’입니다. 정답 확률 ${pct(p,0)}로 손실 −ln(p) = ${fixed(-Math.log(p))}를 계산합니다. 최고확률 토큰 ‘${best}’를 골라 다음 입력으로 넣지는 않습니다.`;\n   $('tfNextInput').textContent=tfStep===3?'종료 정답의 손실까지 계산하면 이 문장 쌍의 순전파가 끝납니다. 이후 손실을 합산하고 역전파합니다.':`다음 단계의 입력 = 정답 ‘${target[tfStep]}’. 지금 예측해야 할 단어를 미리 입력한 것이 아니라, 다음 위치의 이전 단어로 사용합니다.`;\n  }else{\n   $('tfExplanation').textContent=`Greedy는 ‘${best}’를 선택합니다. 이 생성 경로에서는 정답을 알려 주거나 학습 손실을 계산하지 않습니다.`;\n   $('tfNextInput').textContent=tfStep===3?'선택한 토큰이 <EOS>이므로 이 경로의 생성이 종료됩니다.':`다음 단계의 입력 = 방금 선택한 ‘${best}’. 새 상태 hᴰ${tfStep+1}, cᴰ${tfStep+1}도 함께 이어집니다.`;\n  }\n  $('tfCounter').textContent=`${tfStep+1} / 4 단계`;\n  $('tfPrev').disabled=tfStep===0;$('tfNext').disabled=tfStep===3;\n }\n on('tfTrain','click',()=>{tfMode='train';tfStep=0;updateTeacher();});\n on('tfInfer','click',()=>{tfMode='infer';tfStep=0;updateTeacher();});\n on('tfPrev','click',()=>{tfStep=Math.max(0,tfStep-1);updateTeacher();});\n on('tfNext','click',()=>{tfStep=Math.min(3,tfStep+1);updateTeacher();});\n on('tfReset','click',()=>{tfStep=0;updateTeacher();});\n updateTeacher();\n\n // 3. One scalar coordinate of a standard LSTM state update.\n const lstmDefaults={lc:.8,lf:.9,li:.2,lg:.5,lo:.7};\n function updateLstm(){\n  const [c0,f,i,g,o]=['lc','lf','li','lg','lo'].map(num);\n  Object.keys(lstmDefaults).forEach(id=>$(id+'Val').textContent=fixed(num(id),2));\n  const retain=f*c0,add=i*g,c=retain+add,h=o*Math.tanh(c);\n  $('lstmC').textContent=fixed(c);$('lstmH').textContent=fixed(h);\n  $('lstmCalc').innerHTML=`유지한 옛 정보: ${fixed(f,2)} × ${fixed(c0,2)} = ${fixed(retain)}<br>추가한 새 정보: ${fixed(i,2)} × ${fixed(g,2)} = ${fixed(add)}<br>새 c = ${fixed(retain)} + ${fixed(add)} = ${fixed(c)}<br>새 h = ${fixed(o,2)} × tanh(${fixed(c)}) = ${fixed(h)}`;\n  $('lstmCalc').hidden=!$('lstmDetail').checked;\n }\n Object.keys(lstmDefaults).forEach(id=>on(id,'input',updateLstm));\n on('lstmDetail','change',updateLstm);\n on('lstmReset','click',()=>{Object.entries(lstmDefaults).forEach(([id,v])=>$(id).value=v);$('lstmDetail').checked=true;updateLstm();});\n updateLstm();\n\n // 4. Analytic derivative and a separate SGD update for binary logistic loss.\n let w=0, gradient=null, updates=0;\n $('gw').step='any';\n function drawGradient(message){\n  const p=sigmoid(w);\n  $('gwVal').textContent=fixed(w,4);$('geVal').textContent=fixed(num('ge'),2);\n  $('gradP').textContent=pct(p,3);$('gradLoss').textContent=fixed(-Math.log(p));\n  $('gradValue').textContent=gradient===null?'기울기: 아직 계산하지 않았습니다. ① 역전파 버튼을 누르십시오.':`역전파 결과: dℒ/dw = p − 1 = ${fixed(p,6)} − 1 = ${fixed(gradient,6)}. 가중치 w = ${fixed(w,6)}는 그대로입니다.`;\n  $('gradStep').disabled=gradient===null;\n  if(message)$('gradStatus').textContent=message;\n }\n const changed=()=>{w=num('gw');gradient=null;drawGradient('설정이 바뀌었습니다. 현재 가중치에서 기울기를 다시 계산하십시오.');};\n on('gw','input',changed);\n on('ge','input',()=>{gradient=null;drawGradient('학습률을 바꿨습니다. ① 기울기 계산 후 ② 업데이트를 누르십시오.');});\n on('gradCalc','click',()=>{gradient=sigmoid(w)-1;drawGradient('기울기만 계산했습니다. 정답 확률과 손실은 아직 바뀌지 않았습니다.');});\n on('gradStep','click',()=>{\n  if(gradient===null)return;\n  const old=w,g=gradient,eta=num('ge');w=old-eta*g;updates++;\n  $('gw').max=Math.max(4,Math.ceil(w));$('gw').min=Math.min(-4,Math.floor(w));$('gw').value=w;\n  gradient=null;\n  drawGradient(`업데이트 ${updates}회: w = ${fixed(old,6)} − ${fixed(eta,2)} × (${fixed(g,6)}) = ${fixed(w,6)}. 이 새 가중치로 확률과 손실을 다시 계산했습니다.`);\n });\n on('gradReset','click',()=>{w=0;gradient=null;updates=0;$('gw').min=-4;$('gw').max=4;$('gw').value=0;$('ge').value=.1;drawGradient('① 기울기 계산 → ② 가중치 갱신 순서로 진행하십시오.');});\n drawGradient('① 기울기 계산 → ② 가중치 갱신 순서로 진행하십시오.');\n\n // 5. Sampling frequencies compared to the model distribution, not correctness.\n let sampleMethod='sampling',counts=[0,0,0],last=null;\n const sampleWords=['너를','당신을','그를'];\n const sampleProbabilities=()=>{const a=num('sa')/100;return[a,(1-a)*.75,(1-a)*.25];};\n function updateSampling(){\n  const ps=sampleProbabilities(),total=counts.reduce((a,b)=>a+b,0);\n  $('saVal').textContent=pct(ps[0],0);\n  $('sampleMode').setAttribute('aria-pressed',String(sampleMethod==='sampling'));\n  $('greedyMode').setAttribute('aria-pressed',String(sampleMethod==='greedy'));\n  $('sampleBars').innerHTML=ps.map((p,i)=>`<div class=\"sim-card\"><div style=\"display:flex;justify-content:space-between;gap:8px;font-size:13px;margin-bottom:8px\"><strong>${sampleWords[i]} · 모델 ${pct(p,1)}</strong><span>선택 ${counts[i].toLocaleString()}회</span></div><div class=\"bar-track\"><div class=\"bar-fill ${i===1?'alt':''}\" style=\"width:${total?counts[i]/total*100:0}%\"></div></div><div class=\"note\" style=\"margin-top:5px\">선택 빈도: ${total?pct(counts[i]/total,1):'아직 없음'}</div></div>`).join('');\n  const entropy=-ps.reduce((a,p)=>a+p*Math.log2(p),0);\n  $('sampleStats').textContent=`총 ${total.toLocaleString()}회 선택 · 모델 확률의 합 ${fixed(ps.reduce((a,b)=>a+b,0),2)} · 엔트로피 ${fixed(entropy,3)} bit`;\n  $('sampleLast').textContent=last===null?'아직 선택하지 않았습니다. 버튼을 눌러 실험하십시오.':`가장 최근 선택: ${sampleWords[last]}. ${sampleMethod==='sampling'?'확률이 낮은 후보도 선택될 수 있습니다.':'가장 확률이 큰 후보를 매번 고릅니다.'}`;\n }\n function drawSamples(n){\n  const ps=sampleProbabilities();\n  for(let k=0;k<n;k++){\n   let index;\n   if(sampleMethod==='greedy'){index=ps.indexOf(Math.max(...ps));}\n   else{const u=Math.random();index=u<ps[0]?0:u<ps[0]+ps[1]?1:2;}\n   counts[index]++;last=index;\n  }\n  updateSampling();\n }\n const clearSamples=()=>{counts=[0,0,0];last=null;updateSampling();};\n on('sampleMode','click',()=>{sampleMethod='sampling';clearSamples();});\n on('greedyMode','click',()=>{sampleMethod='greedy';clearSamples();});\n on('sa','input',clearSamples);on('sampleOne','click',()=>drawSamples(1));on('sampleMany','click',()=>drawSamples(1000));on('sampleReset','click',clearSamples);\n updateSampling();\n\n // 6. Explicit complete probability tree, with global top-B pruning.\n let beamStage=0;\n const roots=[{path:'A',p:.6},{path:'B',p:.4}];\n const leaves=[{path:'A → C',root:'A',p:.6*.51},{path:'A → D',root:'A',p:.6*.49},{path:'B → C',root:'B',p:.4*.95},{path:'B → D',root:'B',p:.4*.05}];\n function beamCalculation(width){\n  const chosenRoots=roots.slice().sort((a,b)=>b.p-a.p).slice(0,width);\n  const available=leaves.filter(x=>chosenRoots.some(r=>r.path===x.root));\n  const retained=available.slice().sort((a,b)=>b.p-a.p).slice(0,width);\n  return{chosenRoots,available,retained};\n }\n function updateBeam(){\n  const width=num('beamWidth'),result=beamCalculation(width);\n  $('beamWidthVal').textContent=width;\n  $('beamStage').textContent=['1 / 3 · 첫 토큰','2 / 3 · 둘째 토큰','3 / 3 · 종료'][beamStage];\n  let records;\n  if(beamStage===0){records=roots.map(x=>({...x,selected:result.chosenRoots.some(r=>r.path===x.path),reachable:true}));}\n  else{records=leaves.map(x=>({...x,selected:result.retained.some(r=>r.path===x.path),reachable:result.available.some(r=>r.path===x.path)}));}\n  $('beamPaths').innerHTML=records.map(x=>`<div class=\"beam-path ${x.selected?'selected':'pruned'}\"><div>${beamStage===0?'부분 경로':'경로의 누적 확률'}</div><strong>${esc(x.path)}${beamStage===2?' → &lt;EOS&gt;':''}</strong><div>${fixed(x.p,3)} · ${pct(x.p,1)}</div><span class=\"badge\">${x.selected?'유지':!x.reachable?'앞 단계에서 이미 제외':'이번 단계에서 제외'}</span></div>`).join('');\n  if(beamStage===0)$('beamResult').textContent=width===1?'B=1: A만 남기고 B 경로를 버립니다. 이후 B로 시작하는 번역은 탐색할 수 없습니다.':'B=2: A와 B를 모두 남깁니다. 다음 단계에서 두 경로의 확장 후보를 함께 비교합니다.';\n  else{\n   const best=result.retained[0];\n   $('beamResult').textContent=`${beamStage===2?'최종 선택':'현재 가장 높은 점수'}: ${best.path}${beamStage===2?' → <EOS>':''}, 확률 ${fixed(best.p,3)}. ${width===1?'첫 단계의 Greedy 선택 때문에 전체 최댓값 0.380을 놓칩니다.':'이 예시에서는 B → C의 0.380이 모든 완성 경로 중 가장 큽니다.'}`;\n  }\n  $('beamPrev').disabled=beamStage===0;$('beamNext').disabled=beamStage===2;\n }\n on('beamWidth','input',updateBeam);\n on('beamPrev','click',()=>{beamStage=Math.max(0,beamStage-1);updateBeam();});\n on('beamNext','click',()=>{beamStage=Math.min(2,beamStage+1);updateBeam();});\n on('beamReset','click',()=>{beamStage=0;updateBeam();});\n updateBeam();\n\n })();\n";
